    case ${line} in
      y* | Y*)
        cpack_license_accepted=TRUE;;
      *)
        echo "License not accepted. Exiting ..."
        exit 1;;
    esac
  fi

  if [ "x${cpack_include_subdir}x" = "xx" ]
  then
    echo "By default lattice will be installed in:"
    echo "  \"${toplevel}/lattice-25.01.01-Linux\""
    echo "Do you want to include the subdirectory lattice-25.01.01-Linux?"
    echo "Saying no will install in: \"${toplevel}\" [Yn]: "
    read line leftover
    cpack_include_subdir=TRUE
    case ${line} in
      n* | N*)
        cpack_include_subdir=FALSE
    esac
  fi
fi

if [ "x${cpack_include_subdir}x" = "xTRUEx" ]
then
  toplevel="${toplevel}/lattice-25.01.01-Linux"
  mkdir -p "${toplevel}"
fi
echo
echo "Using target directory: ${toplevel}"
echo "Extracting, please wait..."
echo ""

# take the archive portion of this file and pipe it to tar
# the NUMERIC parameter in this command should be one more
# than the number of lines in this header file
# there are tails which don't understand the "-n" argument, e.g. on SunOS
# OTOH there are tails which complain when not using the "-n" argument (e.g. GNU)
# so at first try to tail some file to see if tail fails if used with "-n"
# if so, don't use "-n"
use_new_tail_syntax="-n"
tail $use_new_tail_syntax +1 "$0" > /dev/null 2> /dev/null || \
    use_new_tail_syntax=""

extractor="pax -r"
command -v pax > /dev/null 2> /dev/null || extractor="tar xf -"

tail $use_new_tail_syntax +313 "$0" | gunzip | \
    (cd "${toplevel}" && ${extractor}) || \
    cpack_echo_exit "Problem unpacking the lattice-25.01.01-Linux"

echo "Unpacking finished successfully"
echo ""

echo "Installing driver..."
echo ""
cd ${toplevel}/"lattice_installation/redist"
# Installs WinDriver. You can modify this and add parameters to ./configure
# script if needed

# Check if kp_lattice is loaded, in case it is loaded,
# remove it before installing the driver
KP_MODULE_NAME="kp_lattice"
if lsmod | grep -q "^$KP_MODULE_NAME "; then
    sudo rmmod "$KP_MODULE_NAME"
    if [ $? -eq 0 ]; then
        echo "Previous installed module $KP_MODULE_NAME removed successfully."
    else
        echo "Failed to remove previous installed module $KP_MODULE_NAME." >&2
        exit 1
    fi
fi

# Installing driver:
./configure
sudo make install

# Uncomment ADDITIONAL_FLAGS from configure.kp and installing kernel plugin:
if test -f configure.kp; then
    sed -i 's/# ADDITIONAL_FLAGS=/ ADDITIONAL_FLAGS=/g' configure.kp
    ./configure.kp
    sudo make install -f makefile.kp
    mv Module.symvers Module_kp.symvers
fi


exit 0
